sys_ux_client_script.required_translations:
[
    {
        "message": "Drafting article..."
    },
    {
        "message": "Use AI to draft this article?"
    }
]

sys_ux_client_script.script:
/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (api.state.isGenAiGenerating) {
    return helpers.translateSync('Drafting article...');
  }
	return helpers.translateSync('Use AI to draft this article?');
}
